import {weeklyTaskSections,weeklyAchievement} from './universe-model.js';
import {UNITS,MODES,taskLevel,modeTotals,measurement,unitInfo,quantitySummary,setting,leaves,ancestry,descendants,shiftDate,weekStart} from './model.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const numberText=n=>new Intl.NumberFormat('ja-JP',{maximumFractionDigits:3}).format(n);
export function quantitySettingsFields(s,id,required=true){const m=measurement(s,id),u=unitInfo(m);return `<section class="task-amount-config"><h3>1日に取り組む量</h3><p class="task-setting-caption">例：本を10ページ読む、30分勉強する</p><div class="task-amount-entry"><label><span class="sr-only">タスク量</span><input type="number" inputmode="decimal" name="daily-amount" data-task-amount min="0.001" max="1000000" step="any" ${required?'required':''} value="${m.dailyAmount??''}" placeholder="10" aria-label="タスク量"></label><label><span class="sr-only">単位</span><select name="quantity-unit" data-quantity-unit required aria-label="単位">${Object.entries(UNITS).map(([k,u])=>`<option value="${k}" ${m.unit===k?'selected':''}>${u.label}</option>`).join('')}<option value="custom" ${m.unit==='custom'?'selected':''}>その他</option></select></label></div><label class="task-custom-unit" data-custom-unit ${m.unit==='custom'?'':'hidden'}>単位の名前<input name="custom-unit" maxlength="12" ${m.unit==='custom'?'required':''} value="${esc(m.customUnit||'')}" placeholder="例：km、曲、セット"></label><div class="task-weekly-target"><label for="weekly-target-${esc(id)}">1週間の目標</label><div class="task-week-target-entry"><input id="weekly-target-${esc(id)}" name="weekly-target" type="number" inputmode="decimal" required min="0.001" max="1000000" step="any" value="${m.weeklyTarget??''}" placeholder="50" aria-label="1週間の目標"><span data-weekly-unit>${esc(u.label)}</span></div><p>この目標に対する達成度を、週の記録に表示します。</p></div><p class="task-amount-preview" data-task-preview>${m.dailyAmount?`取り組む日には、${numberText(m.dailyAmount)}${esc(u.label)}を記録します。`:'量と単位を決めてください。'}</p></section>`}
export function taskLevelFields(a,name='task-level'){const selected=taskLevel(a),options=[{value:'rest',title:'毎日取り組む',days:['rest','busy','full']},{value:'busy',title:'忙しい日も取り組む',days:['busy','full']},{value:'full',title:'余裕がある日だけ',days:['full']}];return `<fieldset class="task-schedule-config"><legend>どんな日に取り組みますか？</legend><p class="task-setting-caption">1つ選ぶと、対象の日が自動で決まります。</p><div class="task-schedule-options">${options.map(o=>`<label class="task-schedule-option"><input type="radio" required name="${esc(name)}" value="${o.value}" ${selected===o.value?'checked':''}><span class="task-schedule-copy"><strong>${o.title}</strong><span class="task-day-tags">${o.days.map(d=>`<span>${MODES[d].icon} ${MODES[d].label}</span>`).join('')}</span></span><span class="task-schedule-check" aria-hidden="true">✓</span></label>`).join('')}</div><p class="task-fixed-note">どの日も、設定した量は同じです。</p></fieldset>`}
export function presetPanel(s,id){const n=s.nodes.find(n=>n.id===id),a=setting(s,id);if(!n)return '';return `<form id="preset-form" data-id="${esc(id)}"><div class="dialog-title"><div><div class="eyebrow">${esc(ancestry(s,id).slice(1,-1).join(' / ')||'自分の宇宙')}</div><h2>${esc(n.name)}</h2></div><button type="button" class="round-button" data-do="close" aria-label="閉じる">×</button></div>${quantitySettingsFields(s,id)}${taskLevelFields(a)}<div class="dialog-actions"><button type="button" class="text-button" data-edit="${esc(id)}">名前・親目標などを編集</button><button class="primary" type="submit">タスクを保存</button></div><button type="button" class="text-button record-adjust-button" data-record-leaf="${esc(id)}">今日の記録を調整</button></form>`}
export function modePickerContent(s,key){const current=s.records[key]?.mode;return `<div class="dialog-title"><div><div class="eyebrow">${Number(key.slice(5,7))}月${Number(key.slice(8))}日</div><h2>今日は、どのペース？</h2></div><button class="round-button" data-do="close" aria-label="閉じる">×</button></div><p class="mode-picker-note">タスクに保存した固定量を、そのまま反映します。</p><div class="quick-mode-options">${['full','busy','rest'].map(k=>{const m=MODES[k],summary=modeTotals(s,k);return `<button data-mode="${k}" data-date="${key}" class="quick-mode ${k} ${current===k?'chosen':''}"><span class="quick-mode-icon">${m.icon}</span><div><strong>${m.label}</strong><small>${summary.count?summary.groups.map(g=>{const q=readableQuantity(g.total,g.dimension,g.unit);return `${numberText(q.amount)}${esc(q.unit)}`}).join(' ・ '):'固定量を設定したタスクはありません'}</small></div><i>${current===k?'✓':'→'}</i></button>`}).join('')}</div>${Object.values(s.logs[key]||{}).some(l=>l.quantity&&l.source!=='mode')?'<p class="footnote">この日だけ修正した量は、そのまま残ります。</p>':''}<div class="mode-picker-footer"><button class="text-button" data-configure-leaves>タスクの量を設定する</button><button class="text-button quiet" data-do="close">あとで</button></div>`}
export function recordPanel(s,id,date,today){const n=s.nodes.find(n=>n.id===id);if(!n)return '';const old=s.logs[date]?.[id],m=old?.quantity?.measurement||measurement(s,id),u=unitInfo(m),week=weekStart(date),summary=quantitySummary(s,week,shiftDate(week,6),id,week===weekStart(today)),group=summary.groups.find(g=>g.dimension===u.dimension),amount=old?.quantity?.amount??m.dailyAmount??'',active=setting(s,id);const increments=u.dimension==='time'?(u.label==='分'?[10,30,60]:[.25,.5,1]):[1,5,10];return `<form id="quantity-form" data-id="${esc(id)}"><div class="dialog-title"><div><div class="eyebrow">${esc(ancestry(s,id).slice(1,-1).join(' / ')||'自分の宇宙')}</div><h2>${esc(n.name)}</h2></div><button type="button" class="round-button" data-do="close" aria-label="閉じる">×</button></div><label>記録する日<input type="date" name="record-date" value="${date}" max="${today}" required></label><label class="quantity-input-label">この日の合計<div class="quantity-input"><input name="amount" type="number" inputmode="decimal" min="0.001" max="1000000" step="any" value="${amount}" placeholder="0" required autofocus><span>${esc(u.label)}</span></div></label><div class="quantity-increments">${increments.map(v=>`<button type="button" data-add-quantity="${v}">＋${numberText(v)}${esc(u.label)}</button>`).join('')}</div><div class="record-week-summary"><span>この週の合計</span><strong>${numberText(group?.total||0)}<small>${esc(group?.unit||(u.dimension==='time'?'時間':u.label))}</small></strong></div>${old&&!old.quantity?'<p class="footnote">この日には以前のチェック記録があります。量はまだ記録されていません。</p>':''}${old?.source==='mode'?'<p class="footnote">モードから反映した量です。この日だけ修正できます。</p>':''}${old?.quantity?'<p class="footnote">保存すると、この日の合計を更新します。過去の記録の単位を使用しています。</p>':'<p class="footnote">1日に何回か取り組んだ場合は、合計量を入力してください。</p>'}${active.type==='once'?'<p class="footnote">記録すると、このタスクは完了になります。</p>':''}<div class="dialog-actions"><button type="button" class="text-button" data-open-preset="${esc(id)}">タスクの量を設定</button><button type="submit" class="primary">量を記録する</button></div>${old?`<button type="button" class="text-button danger remove-quantity" data-remove-quantity="${esc(id)}" data-log-date="${date}">この日の記録を削除</button>`:''}</form>`}
function readableQuantity(amount,dimension,unit){return dimension==='time'&&amount>0&&Math.abs(amount-Math.round(amount))>.00001?{amount:Math.round(amount*60000)/1000,unit:'分'}:{amount,unit}}
export function weeklyPanel(s,{week,scope,today}){
 const end=shiftDate(week,6),current=weekStart(today),summary=quantitySummary(s,week,end,scope,week===current),groups=summary.groups.filter(g=>g.total>0),sections=weeklyTaskSections(s,summary,scope).filter(section=>section.rows.length),dates=Array.from({length:7},(_,i)=>shiftDate(week,i)),editableIds=new Set(leaves(s).map(n=>n.id)),goal=s.nodes.find(n=>n.id===scope),short=d=>`${Number(d.slice(5,7))}/${Number(d.slice(8))}`;
 return `<section class="weekly-record" aria-label="週の記録"><header class="weekly-period"><button class="week-arrow" data-quantity-week="-1" aria-label="前の週">‹</button><div><span>${week.slice(0,4)}年${week===current?' · 今週':''}</span><h1>${short(week)} <i>—</i> ${short(end)}</h1></div><button class="week-arrow" data-quantity-week="1" aria-label="次の週" ${week>=current?'disabled':''}>›</button></header><div class="weekly-filter-row"><button class="weekly-goal-filter" data-do="choose-stats-goal"><span>表示する目標</span><strong>${esc(goal?.name||'すべての目標')}</strong><i>⌄</i></button>${week!==current?'<button class="text-button" data-reset-week>今週へ戻る</button>':''}</div>${groups.length?`<section class="weekly-total-block" aria-label="この週の合計"><h2>この週の合計</h2><div class="weekly-total-values">${groups.map(g=>{const shown=readableQuantity(g.total,g.dimension,g.unit);return `<div><strong>${numberText(shown.amount)}</strong><span>${esc(shown.unit)}</span></div>`}).join('')}</div></section>`:'<p class="weekly-empty-note">この週の記録は、まだありません。</p>'}<div class="weekly-task-sections">${sections.map(section=>`<section class="weekly-goal-section"><h2><span>✧</span>${esc(section.name)}</h2>${section.rows.map(row=>{const shown=readableQuantity(row.amount,row.dimension,row.unit),target=readableQuantity(row.target,row.dimension,row.unit),progress=weeklyAchievement(row.amount,row.target);return `<div class="weekly-task-row"><div><strong>${esc(row.name)}</strong>${row.deleted?'<small>過去のタスク</small>':''}</div><div class="weekly-task-value"><b>${numberText(shown.amount)}</b><span>${esc(shown.unit)}</span>${!row.deleted&&editableIds.has(row.id)?`<button data-record-leaf="${esc(row.id)}" data-log-date="${Object.keys(row.byDate||{}).sort().at(-1)||(end<today?end:today)}" aria-label="${esc(row.name)}の記録を修正">›</button>`:''}</div>${progress?`<div class="weekly-task-progress"><div class="weekly-task-progress-track" role="progressbar" aria-label="${esc(row.name)}の週間目標達成度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress.bar}" aria-valuetext="${progress.percent}%"><i style="width:${progress.bar}%"></i></div><p><span>週間目標 ${numberText(target.amount)}${esc(target.unit)}</span><strong>${progress.percent}%${progress.complete?' 達成':''}</strong></p></div>`:!row.deleted&&editableIds.has(row.id)?`<button class="weekly-target-missing" data-open-preset="${esc(row.id)}">週間目標を設定 →</button>`:''}</div>`}).join('')}</section>`).join('')||'<div class="weekly-empty-tasks"><p>タスクを設定すると、ここで週ごとの量を見られます。</p><button class="text-button" data-view="tree">自分の宇宙へ →</button></div>'}</div>${summary.entries.some(e=>e.source==='mode')?'<p class="weekly-source-note">モードから反映した固定量を含みます。記録はカレンダーから修正できます。</p>':''}${summary.unknown?`<p class="weekly-source-note">量が未記録のチェック ${summary.unknown}件は合計に含めていません。</p>`:''}</section>`
}
export function scopeOptions(s,selected){const root=s.nodes.find(n=>n.parentId===null),out=[];function walk(n,depth){out.push(`<option value="${esc(n.id)}" ${selected===n.id?'selected':''}>${'　'.repeat(depth)}${esc(n.name)}</option>`);s.nodes.filter(c=>c.parentId===n.id).forEach(c=>walk(c,depth+1))}if(root)walk(root,0);return `<option value="all" ${selected==='all'?'selected':''}>宇宙全体</option>`+out.join('')}
